{
  "headline": "Sevoflurane is not on FDA's shortage list; supply traces to a plant with a past OAI and a recent VAI",
  "headline_cites": ["D5", "E13", "E21"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include sevoflurane as of 2026-10-21.",
      "cites": ["D5"]
    },
    {
      "text": "Corvale East holds 41 units of the 1 mL/mL 250 mL presentation at 9 units per day, giving 4.6 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 157 units of the same presentation at 8.5 units per day, giving 18.4 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Both sites' inventory is labeled by Bryant Ranch Prepack (NDC 72162224502).",
      "cites": ["E2", "E4"]
    },
    {
      "text": "The label identifies the manufacturing plant as Bryant Ranch Prepack (FEI 1000519407).",
      "cites": ["E23"]
    },
    {
      "text": "FDA inspected that plant on 2009-06-11 and classified it OAI.",
      "cites": ["E13"]
    },
    {
      "text": "The most recent inspection ended 2026-07-16 and was classified VAI.",
      "cites": ["E21"]
    }
  ]
}
